#!/usr/bin/env node
/**
 * Embed source/lib/economic-asset-name-catalog.js into organize_phase_tick.scene.dry
 * for in-browser pickOwnerDisplayName. Run: npm run sync:economic-name-catalog
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const catalogPath = path.join(ROOT, 'source/lib/economic-asset-name-catalog.js')
const tickPath = path.join(
    ROOT,
    'source/scenes/cards/organizing/organize_phase_tick.scene.dry',
)

const BEGIN = '// BEGIN sync:economic-name-catalog'
const END = '// END sync:economic-name-catalog'

let body = fs.readFileSync(catalogPath, 'utf8')
body = body.replace(/^\/\*\*[\s\S]*?\*\/\s*/, '')
body = body.replace(/^['"]use strict['"]\s*\n/, '')
body = body.replace(/\nmodule\.exports[\s\S]*$/, '')

const block = `${BEGIN} (npm run sync:economic-name-catalog)
function installEconomicNameCatalog(q) {
${body.split('\n').map((line) => '    ' + line).join('\n')}
    q.pickOwnerDisplayName = pickOwnerDisplayName
}
${END}
`

let tick = fs.readFileSync(tickPath, 'utf8')
const re = new RegExp(
    `${BEGIN.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`,
)
if (!re.test(tick)) {
    const insertBefore = 'function ensureEconomicAssets()'
    if (!tick.includes(insertBefore)) {
        console.error('sync-economic-name-catalog: anchor not found in organize_phase_tick')
        process.exit(1)
    }
    tick = tick.replace(insertBefore, `${block}\n\n${insertBefore}`)
} else {
    tick = tick.replace(re, block.trimEnd())
}

fs.writeFileSync(tickPath, tick)
console.log('sync-economic-name-catalog: updated organize_phase_tick.scene.dry')

