function formatEconomicAssetsReportHtml() {
    ensureEconomicAssets()
    var assets = Q.economicAssets
    if (!assets || !assets.length) {
        return '<p><em>No registered homes or economic assets yet.</em></p>'
    }

    var stratumLabels = {
        rich: 'Rich',
        first: '1st Wave',
        second: '2nd Wave',
        coop: 'Coops',
        drone: 'Drones',
        alien: 'Otherworlders',
        deeper: 'Deepers',
        third_wave: '3rd Wave',
    }

    function ownerLabel(entry) {
        if (entry.ownerType === 'ig') {
            var color = '#44b88f'
            var tag = 'Corp'
            if (
                entry.owner === 'Families'
                || entry.owner === 'Edges'
                || entry.owner === 'Sharks'
            ) {
                color = '#cf6e19'
                tag = 'Syndicate'
            }
            return (
                '<span style="color:' + color + ';">' + entry.owner + '</span> (' + tag + ')'
            )
        }
        if (entry.ownerType === 'public') {
            var forLabel = entry.housingFor
                ? (stratumLabels[entry.housingFor] || entry.housingFor)
                : 'general'
            return 'City (' + forLabel + ' housing)'
        }
        var stratumName = stratumLabels[entry.owner] || entry.owner
        return stratumName + ' (stratum)'
    }

    var rows = assets.slice().sort(function(a, b) {
        if (a.district !== b.district) {
            return a.district < b.district ? -1 : 1
        }
        if (!!a.countsAsHome !== !!b.countsAsHome) {
            return a.countsAsHome ? -1 : 1
        }
        var an = a.name || a.id
        var bn = b.name || b.id
        return an < bn ? -1 : (an > bn ? 1 : 0)
    })

    var html = '<table style="width:100%;border-collapse:collapse;font-size:0.85em;margin:0.25em 0;">'
    html += '<tr><th style="text-align:left;font-weight:normal;">Site</th>'
    html += '<th style="text-align:left;font-weight:normal;">Type</th>'
    html += '<th style="text-align:left;font-weight:normal;">District</th>'
    html += '<th style="text-align:left;font-weight:normal;">Affiliation</th>'
    html += '<th style="text-align:left;font-weight:normal;">Status</th></tr>'

    for (var i = 0; i < rows.length; i++) {
        var e = rows[i]
        var typeLabel = e.countsAsHome ? 'Home' : 'Asset'
        if (e.kind) { typeLabel += ' (' + e.kind + ')' }
        var status = (e.health == null || Number(e.health) >= 1) ? 'Operational' : 'Offline'
        html += '<tr><td style="text-align:left;">' + (e.name || e.id) + '</td>'
        html += '<td style="text-align:left;">' + typeLabel + '</td>'
        html += '<td style="text-align:left;">' + (e.district || '') + '</td>'
        html += '<td style="text-align:left;">' + ownerLabel(e) + '</td>'
        html += '<td style="text-align:left;">' + status + '</td></tr>'
    }

    html += '</table>'
    html += '<p style="font-size:0.85em;margin:0.35em 0 0 0;">'
    html += rows.length + ' sites registered.</p>'
    return html
}

