var ECONOMIC_STRATUM_LABELS = {
    rich: 'Rich',
    first: '1st Wave',
    second: '2nd Wave',
    coop: 'Coops',
    drone: 'Drones',
    alien: 'Otherworlders',
    deeper: 'Deepers',
    third_wave: '3rd Wave',
}

function sortedEconomicAssets() {
    ensureEconomicAssets()
    var assets = Q.economicAssets || []
    return assets.slice().sort(function(a, b) {
        if (a.district !== b.district) {
            return a.district < b.district ? -1 : 1
        }
        if (!!a.countsAsHome !== !!b.countsAsHome) {
            return a.countsAsHome ? -1 : 1
        }
        var an = a.name || a.id
        var bn = b.name || b.id
        return an < bn ? -1 : (an > bn ? 1 : 0)
    })
}

function economicAssetTypeLabel(entry) {
    var typeLabel = entry.countsAsHome ? 'Home' : 'Asset'
    if (entry.kind) { typeLabel += ' (' + entry.kind + ')' }
    return typeLabel
}

function economicAssetStatusLabel(entry) {
    return (entry.health == null || Number(entry.health) >= 1) ? 'Operational' : 'Offline'
}

function appendEconomicReportCell(tr, text, tagName) {
    var cell = document.createElement(tagName || 'td')
    cell.style.textAlign = 'left'
    cell.style.padding = '0.15em 0.35em 0.15em 0'
  if (tagName === 'th') {
        cell.style.fontWeight = 'normal'
    }
    cell.textContent = text
    tr.appendChild(cell)
    return cell
}

function appendEconomicAffiliationCell(tr, entry) {
    var td = document.createElement('td')
    td.style.textAlign = 'left'
    td.style.padding = '0.15em 0.35em 0.15em 0'

    if (entry.ownerType === 'ig') {
        var color = '#44b88f'
        var tag = 'Corp'
        if (
            entry.owner === 'Families'
            || entry.owner === 'Edges'
            || entry.owner === 'Sharks'
        ) {
            color = '#cf6e19'
            tag = 'Syndicate'
        }
        var span = document.createElement('span')
        span.style.color = color
        span.textContent = entry.owner
        td.appendChild(span)
        td.appendChild(document.createTextNode(' (' + tag + ')'))
    } else if (entry.ownerType === 'public') {
        var forLabel = entry.housingFor
            ? (ECONOMIC_STRATUM_LABELS[entry.housingFor] || entry.housingFor)
            : 'general'
        td.textContent = 'City (' + forLabel + ' housing)'
    } else {
        var stratumName = ECONOMIC_STRATUM_LABELS[entry.owner] || entry.owner
        td.textContent = stratumName + ' (stratum)'
    }

    tr.appendChild(td)
}

