#!/usr/bin/env node
const { chromium } = require('playwright')

async function main() {
  const browser = await chromium.launch()
  const page = await browser.newPage()
  const logs = []
  page.on('console', (m) => logs.push(`${m.type()}: ${m.text()}`))
  page.on('pageerror', (e) => logs.push(`PAGEERROR: ${e.message}`))

  await page.goto('http://127.0.0.1:8765/', { waitUntil: 'networkidle', timeout: 20000 })
  await page.waitForTimeout(3000)

  const bodyText = await page.locator('body').innerText()
  const info = await page.evaluate(() => ({
    dendryUI: !!window.dendryUI,
    title: window.dendryUI?.game?.title,
    sceneId: window.dendryUI?.dendryEngine?.state?.sceneId,
    stamp: document.getElementById('mikasa-build-stamp')?.textContent,
  }))

  console.log('BODY (500):', bodyText.slice(0, 500).replace(/\n/g, ' | '))
  console.log('INFO:', JSON.stringify(info, null, 2))
  console.log('--- console (first 40) ---')
  logs.slice(0, 40).forEach((l) => console.log(l))

  await browser.close()
}

main().catch((e) => {
  console.error('check-browser-load:', e.message)
  process.exit(1)
})

