#!/usr/bin/env node
/**
 * Dendrynexus tabbed-sidebar builds update out/game.json but leave a vendored
 * out/html/core.js whose window.game={"compiled":"…"} block goes stale. The game
 * actually runs from that embed, so the build-stamp footer can lag by hours.
 *
 * After make-html, copy fresh out/game.json into the core.js prefix.
 *
 * Layout: window.game={"compiled":<JSON.stringify(game.json)>}<webpack bundle>
 * compiled must be a JSON *string* — BrowserUserInterface calls JSON.parse on it.
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const CORE = path.join(ROOT, 'out', 'html', 'core.js')
const GAME_JSON = path.join(ROOT, 'out', 'game.json')
const PREFIX = 'window.game={"compiled":'
/** Webpack bundle immediately after the window.game object (no semicolon). */
const BUNDLE_MARKER = '(function e(t,n,r){function'
/** Closes window.game after the compiled string literal */
const WINDOW_GAME_CLOSE = '}'

function sync() {
  if (!fs.existsSync(CORE)) {
    console.error('sync-core-embedded-game: missing', CORE)
    process.exit(1)
  }
  if (!fs.existsSync(GAME_JSON)) {
    console.error('sync-core-embedded-game: missing', GAME_JSON)
    process.exit(1)
  }

  const core = fs.readFileSync(CORE, 'utf8')
  if (!core.startsWith(PREFIX)) {
    console.error('sync-core-embedded-game: unexpected core.js layout (no', PREFIX, ')')
    process.exit(1)
  }

  const markerAt = core.indexOf(BUNDLE_MARKER)
  if (markerAt === -1) {
    console.error('sync-core-embedded-game: bundle marker not found in core.js')
    process.exit(1)
  }

  const game = fs.readFileSync(GAME_JSON, 'utf8')
  const next = PREFIX + JSON.stringify(game) + WINDOW_GAME_CLOSE + core.slice(markerAt)

  if (next === core) {
    return
  }

  fs.writeFileSync(CORE, next)
  const m = game.match(/build_time_label = '([^']+)'/)
  console.log(
    'sync-core-embedded-game: refreshed embedded game in out/html/core.js'
    + (m ? ` (stamp ${m[1]})` : '')
  )
}

sync()

module.exports = { sync, PREFIX, BUNDLE_MARKER, WINDOW_GAME_CLOSE }

