#!/usr/bin/env node
/**
 * Extract the first on-arrival: {! … !} JavaScript block from a Dendry scene.
 * Used to run scene runtime logic in Node (e.g. simulate-election --from-scene).
 */

const fs = require('fs')
const path = require('path')

const ON_ARRIVAL_RE = /on-arrival:\s*\{!\s*([\s\S]*?)\s*!\}/

function extractOnArrivalJs(scenePath) {
    const text = fs.readFileSync(scenePath, 'utf8')
    const match = text.match(ON_ARRIVAL_RE)
    if (!match) {
        throw new Error(`extract-scene-js: no on-arrival block in ${scenePath}`)
    }
    return match[1].trim()
}

function loadSceneOnArrival(scenePath, options = {}) {
    const js = extractOnArrivalJs(scenePath)
    const Q = options.Q || {}
    global.Q = Q
  // eslint-disable-next-line no-eval
    eval(js)
    return Q
}

if (require.main === module) {
    const scene = process.argv[2]
    if (!scene) {
        console.error('Usage: node scripts/extract-scene-js.js <path/to/scene.dry>')
        process.exit(1)
    }
    const resolved = path.isAbsolute(scene) ? scene : path.join(process.cwd(), scene)
    process.stdout.write(extractOnArrivalJs(resolved))
}

module.exports = { extractOnArrivalJs, loadSceneOnArrival, ON_ARRIVAL_RE }

